{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Resminostat, a cinnamohydroxamic acid HDAC inhibitor structurally close to the query, showed good oral bioavailability in patients, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "SAHA (vorinostat), a hydroxamic acid HDAC inhibitor, had 43% absolute oral bioavailability in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Belinostat (PXD101), another cinnamohydroxamic acid HDAC inhibitor, had 33% oral bioavailability in patients with advanced solid tumors, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "TSU-68, an indole-containing molecule, had 42% absolute oral bioavailability in humans after meals, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "AFN-1252/Debio-1452 showed 83% oral bioavailability in healthy volunteers with minimal first-pass metabolism, supporting high F, though structural similarity is lower.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Ilomastat, a hydroxamic acid with an indole moiety, did not show good oral bioavailability in patients, providing contradictory evidence; its peptide-like structure limits transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Curcumin showed poor oral bioavailability in humans, contradictory evidence, but its polyphenolic beta-diketone structure is far from the query's hydroxamic acid HDAC inhibitor scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest hydroxamic acid HDAC inhibitor analogues (resminostat, belinostat, SAHA) show good-to-moderate oral bioavailability (33–43%) in humans, and the query is panobinostat, an approved oral HDAC inhibitor; despite an ionizable zwitterionic character, the transferable experimental evidence supports F ≥20%. Poorly bioavailable curcumin and ilomastat are structurally less transferable and do not override this.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability value for the query molecule (panobinostat) is provided.",
    "The exact human F for panobinostat is not in the evidence set; the closest analogues are not identical.",
    "The impact of the low neutral fraction and possible hydroxamic acid metabolism on F is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

